      bb = J.unionBB(bb, J.mainDraw(env, { text: ln, font: p.font, size: s, x: i < capLines ? x0 + capW + L.gap : x0, y: lineY(i), align: 'left', track: tr, color: sc.fg, mi: 2 + i * 2 }));
