    const al = a1 + a2 * (1 - a1), o = (j * px + i) * 4;
    if (al <= 0.003) { d[o + 3] = 0; continue; }
    const f = a2 * (1 - a1) / al;
    d[o] = A[0] + (B[0] - A[0]) * f; d[o + 1] = A[1] + (B[1] - A[1]) * f; d[o + 2] = A[2] + (B[2] - A[2]) * f; d[o + 3] = Math.round(255 * clamp(al));
