          const x = g.x * sx + (c ? c.dx || 0 : 0), y = g.y * sy + (c ? c.dy || 0 : 0);
          const ox = i.vertical ? g.w * sx * 0.55 * s : g.w * sx * 0.52 * s, oy = i.vertical ? -g.h * sy * 0.3 * s : -g.h * sy * 0.42 * s;
