        if (Pm.from === 'scale') { size *= 1 + 1.6 * f; alpha = clamp(q * 5); rot = f * 8 * (i % 2 ? 1 : -1); }
        else if (Pm.from === 'drop') { y -= H * 0.7 * Math.pow(1 - clamp(q), 2); }
        else { x += (i % 2 ? 1 : -1) * W * 0.9 * f; }
