      if (i > 0) {
        const pd = rotV(1, 0, a), na = a + 90 * Pm.sgn * (i % 2 ? 1 : -1), nd = rotV(1, 0, na);
        const pe = ch[i - 1];
        sx0 = pe.ex - pd[0] * lastAdv[i - 1] * 0.5 + nd[0] * 0.62; sy0 = pe.ey - pd[1] * lastAdv[i - 1] * 0.5 + nd[1] * 0.62;
        a = na;
      }
