    for (let i = 1; i < all.length; i++) { acc += gcount(all[i - 1]); const d = Math.abs(acc - tot / 2); if (d < bd) { bd = d; best = i; } }
    const A = all.slice(0, best).join(lat ? ' ' : ''), B = all.slice(best).join(lat ? ' ' : '');
