      const it = { text: t, font: Pm.font, size, x: p[0] + (axis ? 0 : o) + J.rs(c.seed, env.step, sgn, 1) * jit, y: p[1] + (axis ? o : 0) + J.rs(c.seed, env.step, sgn, 2) * jit, track: 0.02, color: col, mi: 0 };
