      const b = G.wb[j], k = kOf(G, g, it), [gx, gy] = gpos(g, it);
      const ww = Math.max(1e-3, G.vert ? b.y1 - b.y0 : b.x1 - b.x0), big = Math.min(2.4, Math.max(1, bw / ww * 0.8));
